<?php declare(strict_types=1);use FastWebsite\Core\View;$v=static fn(string$f):string=>(string)($values[$f]??'');$editing=is_int($itemId);?><section class="admin-page-heading"><div><h1><?=$editing?'Edit equipment':'Create equipment'?></h1></div><a class="button button-secondary" href="<?=View::escape($baseUrl)?>admin/facilities#equipment">Cancel</a></section><?php if($errors!==[]):?><div class="form-alert"><ul><?php foreach($errors as$error):?><li><?=View::escape($error)?></li><?php endforeach;?></ul></div><?php endif;?><form class="content-form" method="post" action="<?=View::escape($baseUrl)?>admin/facilities/equipment<?=$editing?'/'.$itemId:''?>"><input type="hidden" name="_token" value="<?=View::escape($csrfToken)?>"><section class="form-section"><div class="form-grid"><div class="form-field span-2"><label for="name">Equipment name *</label><input id="name" name="name" required maxlength="255" value="<?=View::escape($v('name'))?>"></div><div class="form-field"><label for="research_unit_id">Research unit *</label><select id="research_unit_id" name="research_unit_id" required><?php foreach($units as$u):?><option value="<?=(int)$u['id']?>"<?=$v('research_unit_id')===(string)$u['id']?' selected':''?>><?=View::escape($u['name'])?></option><?php endforeach;?></select></div><div class="form-field"><label for="facility_id">Facility</label><select id="facility_id" name="facility_id"><option value="">No facility</option><?php foreach($facilities as$f):?><option value="<?=(int)$f['id']?>"<?=$v('facility_id')===(string)$f['id']?' selected':''?>><?=View::escape($f['name'])?></option><?php endforeach;?></select></div><?php foreach(['manufacturer'=>'Manufacturer','model'=>'Model','asset_reference'=>'Asset reference']as$f=>$label):?><div class="form-field"><label for="<?=$f?>"><?=$label?></label><input id="<?=$f?>" name="<?=$f?>" value="<?=View::escape($v($f))?>"></div><?php endforeach;?><div class="form-field"><label for="availability_status">Availability</label><select id="availability_status" name="availability_status"><?php foreach(['available','restricted','maintenance','unavailable','retired']as$status):?><option value="<?=$status?>"<?=$v('availability_status')===$status?' selected':''?>><?=ucfirst($status)?></option><?php endforeach;?></select></div><div class="form-field"><label for="status">Record status</label><select id="status" name="status"><?php foreach(['active','inactive','archived']as$status):?><option value="<?=$status?>"<?=$v('status')===$status?' selected':''?>><?=ucfirst($status)?></option><?php endforeach;?></select></div><div class="form-field span-2"><label for="capabilities">Capabilities</label><textarea id="capabilities" name="capabilities" rows="6"><?=View::escape($v('capabilities'))?></textarea></div><div class="form-field span-2"><label for="booking_information">Booking information</label><textarea id="booking_information" name="booking_information" rows="4"><?=View::escape($v('booking_information'))?></textarea></div><div class="form-field checkbox-field"><label><input type="checkbox" name="external_use_allowed" value="1"<?=$v('external_use_allowed')==='1'?' checked':''?>> External use allowed</label></div></div></section><button class="button button-primary">Save equipment</button></form>
